import { createClient } from '@supabase/supabase-js';
import type { Database } from './types';
import { authResilientFetch } from './authFetch';
/* NEXO_CHAT_GOOGLE_RETURN_V3 */
import { getChatOAuthReturn } from '@/lib/chatOAuthReturn';

export { authResilientFetch } from './authFetch';

const SUPABASE_URL = import.meta.env.VITE_SUPABASE_URL;
const SUPABASE_PUBLISHABLE_KEY = import.meta.env.VITE_SUPABASE_PUBLISHABLE_KEY;
const isPlayerAuthRoute = typeof window !== "undefined" && (
  /^\/(?:[^/]+\/)?player(?:\/|$)/.test(window.location.pathname) ||
  window.location.pathname.endsWith("/auth/popup-callback") ||
  /^\/[^/]+\/pair\/?$/.test(window.location.pathname) ||
  (window.location.pathname === "/" && Boolean(getChatOAuthReturn()))
);

// Import the supabase client like this:
// import { supabase } from "@/integrations/supabase/client";

export const supabase = createClient<Database>(SUPABASE_URL, SUPABASE_PUBLISHABLE_KEY, {
  global: { fetch: authResilientFetch },
  auth: {
    persistSession: true,
    autoRefreshToken: true,
    // The Player OAuth callback is handled only by playerSupabase with its own
    // storage key. The dashboard client must never consume Player URL tokens.
    detectSessionInUrl: typeof window === "undefined" || !isPlayerAuthRoute,
  }
});

// Intercept edge functions to provide resilient local and direct operations
import { invokeWeatherFunction } from '@/lib/weatherService';
import { invokeFetchRss, invokeFetchRssTitles } from '@/lib/rssService';
import { invokeDesktopFreeAi } from '@/lib/desktopFreeAi';

const originalInvoke = supabase.functions.invoke.bind(supabase.functions);
supabase.functions.invoke = (async (functionName: string, options?: any) => {
  if (window.houseMixDesktop?.generateLocalText) {
    const result = await invokeDesktopFreeAi(functionName, options?.body);
    if (result) return result;
  }
  if (functionName === "fetch-weather") {
    return invokeWeatherFunction(options?.body);
  }
  if (functionName === "fetch-rss") {
    return invokeFetchRss(options?.body);
  }
  if (functionName === "fetch-rss-titles") {
    return invokeFetchRssTitles(options?.body);
  }
  return originalInvoke(functionName, options);
}) as any;

// Also intercept direct fetch calls aimed at supabase functions.
// Only in dev: the /api/* middleware exists solely in the Vite dev server, so in a
// published build the direct edge-function URL must be left untouched.
if (typeof window !== "undefined" && import.meta.env.DEV) {
  const origFetch = window.fetch.bind(window);
  window.fetch = (async (input: RequestInfo | URL, init?: RequestInit) => {
    try {
      const url = typeof input === "string" ? input : input instanceof URL ? input.href : (input as any)?.url || "";
      if (url.includes("/functions/v1/fetch-rss-titles")) {
        return origFetch("/api/fetch-rss-titles", init);
      }
      if (url.includes("/functions/v1/fetch-rss")) {
        return origFetch("/api/fetch-rss", init);
      }
    } catch {}
    return origFetch(input, init);
  }) as typeof window.fetch;
}
